def transform(grid):
    out=[row[:] for row in grid]
    for r in range(len(grid)-2):
        for c in range(len(grid[0])-2):
            border=[grid[r+i][c+j] for i in range(3) for j in range(3) if i!=1 or j!=1]
            center=grid[r+1][c+1]; color=border[0]
            if color and all(x==color for x in border) and center!=color:
                if center==1: replacement=3
                elif color==1 and center==3: replacement=3
                elif color==1 and center==4: replacement=8
                elif center in (3,4): replacement=2
                else: replacement=0
                if replacement: out[r+1][c+1]=replacement
                else:
                    for rr in range(r,r+3):
                        for cc in range(c,c+3): out[rr][cc]=0
    return out

